base.ops/services/bene-prefs/main.tf:
terraform {
  backend "s3" {}
}
module "terraservice" {
  source = "../../modules/terraservice"
}
locals {
  env = module.terraservice.env
}
resource "aws_dynamodb_table" "bene_preferences_tracker" {
  count        = contains(["test", "prod"], local.env) ? 1 : 0
  name         = "bfd-${local.env}-bene-preferences"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"
  attribute {
    name = "id"
    type = "S"
  }
}

base.ops/modules/terraservice/main.tf:
locals {
  established_envs = ["test", "sandbox", "prod"]
  parent_env       = try(one([for x in local.established_envs : x if endswith(terraform.workspace, x)]), null)
  env              = terraform.workspace
}
output "env" {
  value = local.env
}

